import{_ as i,l as n,o as e,c as l,v as r,p as s,x as t,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"分治","description":"","frontmatter":{"title":"分治","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/divide-conquer.md","filePath":"cs/divide-conquer.md","lastUpdated":1789023840000}'),c={name:"cs/divide-conquer.md"};function E(u,a,A,m,_,T){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="分治" tabindex="-1">分治 <a class="header-anchor" href="#分治" aria-label="Permalink to &quot;分治&quot;">​</a></h1><div class="epigraph"><p>把问题切成同类子问题，递归解完再合并；代价由切法与合并共同决定。</p><footer>—— 据 Knuth, The Art of Computer Programming, vol. 3；CLRS 第 2、4 章整理</footer></div><p>上一课<a href="/cs/akra-bazzi">Akra–Bazzi 对照</a>已经能读 \\(T(n)=aT(n/b)+f(n)\\)。本课不重证三种情形。缺口是：递归式从哪来。数据结构课给了数组、树、图的表示，没有说「把规模对半切」是一种设计。本课只钉分治三步：分解、递归、合并；具体排序算法下一课才写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>循环不变式适合<strong>同一数组上逐步扩大前缀</strong>。有些问题前缀扩不成：左右两半各自有解，合在一起才是原问题的解。若不会分解，就只剩 \\(O(n^2)\\) 的双重循环。缺口不是渐近记号，而是承认子问题与原问题同型，规模严格变小，合并是显式步骤。</p><p>本课不引入动态规划。分治的子问题通常不相交或几乎不相交；重叠子问题是<a href="/cs/dynamic-programming">后课</a>的缺口。这里只要求：切完能递归，合完满足原问题的后置条件。</p><h3 id="分治不是「递归」的别名" tabindex="-1">分治不是「递归」的别名 <a class="header-anchor" href="#分治不是「递归」的别名" aria-label="Permalink to &quot;分治不是「递归」的别名&quot;">​</a></h3><p>递归是控制结构；分治是切问题的方式。深度优先搜索也递归，但不是按规模等分再合并答案。尾递归循环更不是分治。后课见到 <code>recurse(left); recurse(right); merge</code> 才叫本课的对象。</p><p><span class="marginnote">Knuth 把归并当作外存与内排的共同骨架。CLRS 用归并引入分治，再用主定理收阶。本课把「范式」从「某一个排序」里抽出来，避免下一课重讲切法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>指定如何把输入分成 \\(a\\) 块（常 \\(a=2\\)、\\(b=2\\)），对每块调用同一过程，再写合并。正确性：子问题规模小于 \\(n\\)，基准情形直接解；归纳假设子解正确，证明合并保持后置条件。代价：写出 \\(T(n)\\)，套主定理。</p>',11)),(e(),s(p,null,{default:t(()=>[h(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E8%A7%84%E6%A8%A1%20n%20%E7%9A%84%E9%97%AE%E9%A2%98%22%5D%20--%3E%20SPLIT%5B%22%E5%88%86%E8%A7%A3%E6%88%90%20a%20%E5%9D%97%22%5D%0A%20%20SPLIT%20--%3E%20REC%5B%22%E9%80%92%E5%BD%92%E8%A7%A3%E5%AD%90%E9%97%AE%E9%A2%98%22%5D%0A%20%20REC%20--%3E%20MERGE%5B%22%E5%90%88%E5%B9%B6%22%5D%0A%20%20MERGE%20--%3E%20ANS%5B%22%E5%8E%9F%E9%97%AE%E9%A2%98%E7%9A%84%E8%A7%A3%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>分解本身可以是 \\(\\Theta(1)\\)（中点下标）或 \\(\\Theta(n)\\)（复制到新数组）。合并可以是 \\(\\Theta(n)\\)（归并）或 \\(\\Theta(1)\\)（最大值在根）。主定理里的 \\(f\\) 就是分解加合并。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分治把空间也切开：每层可以新开缓冲，总额外空间常 \\(\\Theta(n)\\)；就地切（快排分区）把额外空间压到递归栈。本课不选定哪一种，只声明空间是合并策略的一部分。后课插入是循环，归并是分治，对照才有意义。</p><p>并行直觉（两半可同时算）本课点到为止：正确性不依赖并行；只是 \\(a\\) 个子问题在数据上不相依。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>分治不保证比循环快。切得不均衡，主定理的 \\(b\\) 失效，最坏可以退回平方。也不自动处理图上的全局约束：最短路不是「左右两半的最短路再拼」。图算法仍走 BFS/松弛，不套本课模板。</p><p>后课默认：说到分治，就是分解–递归–合并，递归式用主定理读。插入与归并的对照是下一课的缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分治 = 同类子问题 + 规模下降 + 显式合并。</li><li>正确性走递归归纳；代价走主定理。</li><li>子问题重叠不是本课；图上的全局最优也不是。</li><li>出处：Knuth, TAOCP vol. 3；CLRS 第 2、4 章。</li></ul>',9))])}const q=i(c,[["render",E]]);export{b as __pageData,q as default};
